305	func TestManager_StartStop(t *testing.T) {
306		cfg := &config.Config{
307			Models: map[string]config.ModelParams{
308				"org/test-model": {Slots: 1},
309			},
310			Warmup:    []string{"org/test-model"},
311			MaxModels: 1,
312		}
313		m := newTestManager(cfg)
314	
315		ctx, cancel := context.WithCancel(context.Background())
316		defer cancel()
317	
318		if err := m.Start(ctx); err != nil {
319			t.Fatalf("Start: %v", err)
320		}
321	
322		// Poll until healthy (up to 10s for the subprocess to spin up).
323		deadline := time.Now().Add(10 * time.Second)
324		for time.Now().Before(deadline) {
325			if m.Loaded("org/test-model") {
326				break
327			}
328			time.Sleep(100 * time.Millisecond)
329		}
330	
331		if !m.Loaded("org/test-model") {
332			t.Fatal("model did not become healthy within 10s")
333		}
334	
335		addr, ok := m.Addr("org/test-model")
336		if !ok {
337			t.Fatal("Addr: expected ok=true after healthy")
338		}
339		if addr == "" {
340			t.Error("Addr: returned empty string")
341		}
342	
343		running := m.RunningModels()
344		if len(running) != 1 || running[0] != "org/test-model" {
345			t.Errorf("RunningModels: got %v, want [org/test-model]", running)
346		}
347	
348		if err := m.Stop(); err != nil {
349			t.Errorf("Stop: %v", err)
350		}
351	
352		if m.Loaded("org/test-model") {
353			t.Error("Loaded: expected false after Stop")
354		}
