361	// TestLoadOrGet_Coalescing verifies that 10 concurrent requests for the same
362	// unloaded model coalesce to a single process start.
363	func TestLoadOrGet_Coalescing(t *testing.T) {
364		cfg := &config.Config{
365			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
366			MaxModels: 1,
367		}
368		m := New(cfg, slog.Default())
369		// 200 ms startup delay to ensure all goroutines arrive before healthy.
370		m.cmdBuilder = testCmdBuilderWithDelay(200)
371	
372		ctx, cancel := context.WithCancel(context.Background())
373		defer cancel()
374		if err := m.Start(ctx); err != nil {
375			t.Fatalf("Start: %v", err)
376		}
377	
378		params := config.ModelParams{Slots: 1}
379		const n = 10
380		addrs := make([]string, n)
381		var wg sync.WaitGroup
382		wg.Add(n)
383		for i := range n {
384			go func(i int) {
385				defer wg.Done()
386				addr, release, err := m.LoadOrGet(ctx, "org/model-a", params)
387				if err != nil {
388					t.Errorf("goroutine %d: LoadOrGet error: %v", i, err)
389					return
390				}
391				defer release()
392				addrs[i] = addr
393			}(i)
394		}
395		wg.Wait()
396	
397		// All goroutines must have gotten a non-empty addr.
398		first := addrs[0]
399		if first == "" {
400			t.Fatal("got empty addr")
401		}
402		for i, a := range addrs {
403			if a != first {
404				t.Errorf("goroutine %d: got addr %q, want %q (coalescing failed)", i, a, first)
405			}
406		}
407	
408		// Only one process should have been started.
409		if len(m.RunningModels()) != 1 {
410			t.Errorf("RunningModels: expected 1, got %d", len(m.RunningModels()))
411		}
412	}
