414	// TestLoadOrGet_LRUEviction verifies that when max_models=1 and model A is
415	// loaded, requesting model B evicts A and loads B. Requesting A again evicts B
416	// and reloads A.
417	func TestLoadOrGet_LRUEviction(t *testing.T) {
418		cfg := &config.Config{
419			Models: map[string]config.ModelParams{
420				"org/model-a": {Slots: 1},
421				"org/model-b": {Slots: 1},
422			},
423			Warmup:    []string{"org/model-a"},
424			MaxModels: 1,
425		}
426		m := newTestManager(cfg)
427	
428		ctx, cancel := context.WithCancel(context.Background())
429		defer cancel()
430		if err := m.Start(ctx); err != nil {
431			t.Fatalf("Start: %v", err)
432		}
433	
434		// Wait for warmup model A to become healthy.
435		waitLoadedModel(t, m, "org/model-a", 10*time.Second)
436	
437		// Request model B: should evict A and load B.
438		addrB, releaseB, err := m.LoadOrGet(ctx, "org/model-b", cfg.Models["org/model-b"])
439		if err != nil {
440			t.Fatalf("LoadOrGet model-b: %v", err)
441		}
442		if addrB == "" {
443			t.Fatal("got empty addr for model-b")
444		}
445		releaseB()
446	
447		if m.Loaded("org/model-a") {
448			t.Error("model-a should have been evicted")
449		}
450		if !m.Loaded("org/model-b") {
451			t.Error("model-b should be healthy")
452		}
453	
454		// Request model A again: should evict B and reload A.
455		addrA2, releaseA2, err := m.LoadOrGet(ctx, "org/model-a", cfg.Models["org/model-a"])
456		if err != nil {
457			t.Fatalf("LoadOrGet model-a (reload): %v", err)
458		}
459		if addrA2 == "" {
460			t.Fatal("got empty addr for model-a reload")
461		}
462		releaseA2()
463	
464		if m.Loaded("org/model-b") {
465			t.Error("model-b should have been evicted on second request")
466		}
467		if !m.Loaded("org/model-a") {
468			t.Error("model-a should be healthy after reload")
469		}
470	}
