package vram

import (
	"context"
	"log/slog"
	"sync"
	"time"

	"github.com/nogo/wire/internal/monitor"
)

// Tracker manages VRAM budget tracking, admission control, and sysfs reconciliation.
type Tracker struct {
	backend      Backend
	hfCache      *HFCache
	estimates    sync.Map // modelRef → uint64 (VRAM estimate bytes)
	reservations sync.Map // modelRef → uint64 (reserved bytes)
	pending      sync.Map // modelRef → uint64 (pending release, waiting for sysfs confirmation)

	gpuStateCh chan []monitor.GPUMetrics // published to Hub

	totalVRAM uint64
	mu        sync.RWMutex

	ctx    context.Context
	cancel context.CancelFunc
	wg     sync.WaitGroup
}

// New creates a Tracker with the given backend and HF cache scanner.
// Call Discover() then Start() to begin tracking.
func New(backend Backend, hfCache *HFCache) *Tracker {
	ctx, cancel := context.WithCancel(context.Background())
	return &Tracker{
		backend:    backend,
		hfCache:    hfCache,
		gpuStateCh: make(chan []monitor.GPUMetrics, 64),
		ctx:        ctx,
		cancel:     cancel,
	}
}

// HFCache returns the HF cache scanner for manual scanning if needed.
func (t *Tracker) HFCache() *HFCache {
	return t.hfCache
}

// Discover runs the backend auto-detection chain and populates totalVRAM.
// Returns the discovered GPUs.
func (t *Tracker) Discover() []monitor.GPUInfo {
	gpus := t.backend.Discover()
	if t.backend.IsNoop() {
		slog.Info("VRAM tracker: noop backend (CPU-only)")
		return gpus
	}
	t.mu.Lock()
	t.totalVRAM = t.backend.TotalVRAM()
	t.mu.Unlock()
	slog.Info("VRAM tracker: discovered GPUs", "count", len(gpus), "total_vram", t.totalVRAM)
	return gpus
}

// CanFit reports whether estimate bytes would fit in the current VRAM budget.
// Budget = total - (actual_sysfs_used + pending_releases).
func (t *Tracker) CanFit(estimate uint64) bool {
	if t.backend.IsNoop() {
		return true
	}
	t.mu.RLock()
	total := t.totalVRAM
	t.mu.RUnlock()

	actualUsed := t.backend.UsedVRAM()
	pending := t.pendingTotal()

	sum := actualUsed + pending
	if sum >= total {
		return false
	}
	return estimate <= total-sum
}

// Reserve marks VRAM for a model. estimate is the expected VRAM consumption.
// Returns false if the model is already reserved or if it would exceed budget.
func (t *Tracker) Reserve(model string, estimate uint64) bool {
	if t.backend.IsNoop() {
		return true
	}
	if _, loaded := t.reservations.LoadOrStore(model, estimate); loaded {
		return true // already reserved
	}
	if !t.CanFit(estimate) {
		t.reservations.Delete(model)
		return false
	}
	slog.Info("VRAM reserved", "model", model, "bytes", estimate)
	return true
}

// Release marks a model's VRAM as pending release.
// The reservation is moved to pending until sysfs reconciliation confirms the drop.
func (t *Tracker) Release(model string) {
	if t.backend.IsNoop() {
		return
	}
	if v, loaded := t.reservations.LoadAndDelete(model); loaded {
		t.pending.Store(model, v)
		slog.Info("VRAM release pending", "model", model, "bytes", v)
	}
}

// EstimateForModel returns the VRAM estimate for a model reference.
// It checks the HF cache scan first, then tries to stat the path directly.
func (t *Tracker) EstimateForModel(modelRef string) uint64 {
	if t.hfCache != nil {
		if v := t.hfCache.Estimate(modelRef); v > 0 {
			return v
		}
	}
	if v, ok := t.estimates.Load(modelRef); ok {
		return v.(uint64)
	}
	// Try placeholder based on model name.
	if v := PlaceholderVRAM(modelRef); v > 0 {
		t.estimates.Store(modelRef, v)
		return v
	}
	return 0
}

// SetEstimate records a VRAM estimate for a model reference.
func (t *Tracker) SetEstimate(modelRef string, estimate uint64) {
	t.estimates.Store(modelRef, estimate)
}

// GPUStateCh returns a receive-only channel that delivers GPU metrics snapshots.
// Hub subscribes to this channel for MsgGPUTick messages.
func (t *Tracker) GPUStateCh() <-chan []monitor.GPUMetrics {
	return t.gpuStateCh
}

// Start begins the poll loop that reconciles reservations with sysfs readings.
func (t *Tracker) Start() {
	t.wg.Add(1)
	go t.pollLoop()
}

// Stop cancels the poll loop and waits for it to exit.
func (t *Tracker) Stop() {
	t.cancel()
	t.wg.Wait()
	close(t.gpuStateCh)
}

// pendingTotal returns the sum of all pending-release VRAM.
func (t *Tracker) pendingTotal() uint64 {
	var total uint64
	t.pending.Range(func(_, v interface{}) bool {
		total += v.(uint64)
		return true
	})
	return total
}

// reservedTotal returns the sum of all active reservations.
func (t *Tracker) reservedTotal() uint64 {
	var total uint64
	t.reservations.Range(func(_, v interface{}) bool {
		total += v.(uint64)
		return true
	})
	return total
}

func (t *Tracker) pollLoop() {
	defer t.wg.Done()
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-t.ctx.Done():
			return
		case <-ticker.C:
			t.reconcile()
			t.pushGPUState()
		}
	}
}

// reconcile compares sysfs actual VRAM used against tracked reservations+pending,
// and clears stale entries where actual usage has dropped.
func (t *Tracker) reconcile() {
	if t.backend.IsNoop() {
		return
	}
	actualUsed := t.backend.UsedVRAM()
	reserved := t.reservedTotal()
	pending := t.pendingTotal()

	// Clear pending releases where sysfs shows the VRAM has been freed.
	if pending > 0 && actualUsed < reserved+pending {
		t.pending.Range(func(key, val interface{}) bool {
			// If actual usage dropped significantly, assume this model's VRAM was freed.
			if actualUsed <= reserved {
				t.pending.Delete(key)
				slog.Info("VRAM release confirmed by sysfs", "model", key)
			}
			return true
		})
	}

	// If sysfs shows less used than we think is reserved, something was
	// externally freed — clear all reservations to stay aligned.
	if actualUsed < reserved {
		t.reservations.Range(func(key, _ interface{}) bool {
			slog.Warn("VRAM mismatch: sysfs lower than reserved, clearing reservation",
				"model", key, "actual_used", actualUsed, "reserved", reserved)
			t.reservations.Delete(key)
			return true
		})
	}
}

// pushGPUState reads GPU metrics and sends them to the Hub channel.
func (t *Tracker) pushGPUState() {
	metrics := t.backend.ReadMetrics()
	select {
	case t.gpuStateCh <- metrics:
	default:
		// Drop if Hub consumer is slow.
	}
}

package queue

import (
	"context"
	"errors"
	"sync"
	"sync/atomic"
	"time"
)

// Priority determines the time budget for a queued request.
type Priority int

const (
	PriorityHigh   Priority = 0 // chat completions: 30s budget
	PriorityMedium Priority = 1 // completions: 15s budget
	PriorityLow    Priority = 2 // embeddings/rerank: 5s budget
)

var defaultBudgets = [3]time.Duration{
	30 * time.Second,
	15 * time.Second,
	5 * time.Second,
}

var (
	// ErrQueueFull is returned when the global depth cap is exceeded.
	ErrQueueFull = errors.New("queue at capacity")
	// ErrModelEvicted is returned when the model is evicted while the ticket is waiting.
	ErrModelEvicted = errors.New("model evicted")
)

// LoadFunc loads a model and returns its backend address and a release function.
// The release function must be called when the proxied request completes.
type LoadFunc func(ctx context.Context, model string) (addr string, release func(), err error)

// Ticket represents a queued request. Returned immediately by Enqueue.
type Ticket struct {
	ready chan string
	mu    sync.Mutex
	err   error
	rel   func()
	once  sync.Once
}

// Ready returns a channel that receives the backend address on success,
// or is closed without a value on failure. Call Err() to inspect the cause.
func (t *Ticket) Ready() <-chan string {
	return t.ready
}

// Err returns the failure cause. Must be called after Ready() closes or is drained.
func (t *Ticket) Err() error {
	t.mu.Lock()
	defer t.mu.Unlock()
	return t.err
}

// Release decrements the in-flight counter. Must be called exactly once after the request completes.
func (t *Ticket) Release() {
	t.once.Do(func() {
		t.mu.Lock()
		rel := t.rel
		t.mu.Unlock()
		if rel != nil {
			rel()
		}
	})
}

func (t *Ticket) succeed(addr string, rel func()) {
	t.mu.Lock()
	t.rel = rel
	t.mu.Unlock()
	t.ready <- addr
}

func (t *Ticket) fail(err error) {
	t.mu.Lock()
	t.err = err
	t.mu.Unlock()
	close(t.ready)
}

// modelQueue serializes initial loading for a single model.
// Concurrent callers coalesce: the first (primary) calls the loader; subsequent callers
// wait for the primary to finish, then call the loader themselves (which returns immediately
// since the model is already loaded at that point).
type modelQueue struct {
	mu          sync.Mutex
	loading     bool
	loadDone    chan struct{}
	evictCtx    context.Context
	evictCancel context.CancelFunc
}

func (mq *modelQueue) load(ctx context.Context, loader LoadFunc, model string) (string, func(), error) {
	mq.mu.Lock()
	if mq.loading {
		done := mq.loadDone
		mq.mu.Unlock()
		select {
		case <-done:
		case <-ctx.Done():
			return "", nil, ctx.Err()
		}
		// Primary finished. Model is now loaded; this call returns immediately.
		return loader(ctx, model)
	}
	// This goroutine is the primary loader.
	mq.loading = true
	done := make(chan struct{})
	mq.loadDone = done
	mq.mu.Unlock()

	addr, rel, err := loader(ctx, model)

	mq.mu.Lock()
	mq.loading = false
	mq.mu.Unlock()
	close(done)

	return addr, rel, err
}

// Queue manages per-model request queuing with time-bounded priority budgets.
type Queue struct {
	mu       sync.Mutex
	models   map[string]*modelQueue
	depth    atomic.Int64
	maxDepth int64
	loader   LoadFunc
	budgets  [3]time.Duration
}

// New creates a Queue with the given depth cap and loader function.
func New(maxDepth int, loader LoadFunc) *Queue {
	return &Queue{
		models:   make(map[string]*modelQueue),
		maxDepth: int64(maxDepth),
		loader:   loader,
		budgets:  defaultBudgets,
	}
}

// Enqueue registers a request for the given model at the specified priority.
// Returns a Ticket immediately; the caller waits on ticket.Ready() for the backend address.
func (q *Queue) Enqueue(model string, prio Priority, reqCtx context.Context) *Ticket {
	if q.depth.Add(1) > q.maxDepth {
		q.depth.Add(-1)
		t := &Ticket{ready: make(chan string, 1)}
		t.fail(ErrQueueFull)
		return t
	}

	q.mu.Lock()
	mq, ok := q.models[model]
	if !ok {
		evictCtx, evictCancel := context.WithCancel(context.Background())
		mq = &modelQueue{
			evictCtx:    evictCtx,
			evictCancel: evictCancel,
		}
		q.models[model] = mq
	}
	q.mu.Unlock()

	t := &Ticket{ready: make(chan string, 1)}

	go func() {
		defer q.depth.Add(-1)

		// Combined context: cancelled by request cancellation or the priority budget.
		ctx, cancel := context.WithTimeout(reqCtx, q.budgets[prio])
		defer cancel()

		// Also watch for model eviction; cancel the load context if evicted.
		go func() {
			select {
			case <-mq.evictCtx.Done():
				cancel()
			case <-ctx.Done():
			}
		}()

		addr, rel, err := mq.load(ctx, q.loader, model)
		if err != nil {
			select {
			case <-mq.evictCtx.Done():
				t.fail(ErrModelEvicted)
			default:
				t.fail(err)
			}
			return
		}

		// Load succeeded, but eviction may have raced. Check before serving.
		select {
		case <-mq.evictCtx.Done():
			if rel != nil {
				rel()
			}
			t.fail(ErrModelEvicted)
			return
		default:
		}

		t.succeed(addr, rel)
	}()

	return t
}

// CancelModel cancels all tickets for the given model with ErrModelEvicted.
// Call this when a model is being evicted by the process manager.
func (q *Queue) CancelModel(model string) {
	q.mu.Lock()
	mq, ok := q.models[model]
	if ok {
		delete(q.models, model)
	}
	q.mu.Unlock()
	if ok {
		mq.evictCancel()
	}
}

package vram

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

const vramMultiplier = 1.3

// EstimateVRAM returns the estimated VRAM bytes needed to load a GGUF model.
// It stats the file at modelPath and applies the 1.3× heuristic
// (file size + 30% KV cache overhead).
// For on-demand HF models that aren't in the local cache yet,
// it returns a conservative placeholder based on model name pattern.
func EstimateVRAM(modelPath string) (uint64, error) {
	info, err := os.Stat(modelPath)
	if err != nil {
		return 0, fmt.Errorf("stat model %q: %w", modelPath, err)
	}
	if info.IsDir() {
		return 0, fmt.Errorf("model path %q is a directory", modelPath)
	}
	return uint64(float64(info.Size()) * vramMultiplier), nil
}

// PlaceholderVRAM returns a conservative VRAM estimate for a model that
// hasn't been downloaded yet. It parses the model name for known size hints
// (e.g., "7b", "13b", "70b") and uses approximate GGUF sizes.
// Returns 0 if the model name doesn't match any known pattern.
func PlaceholderVRAM(modelName string) uint64 {
	name := strings.ToLower(modelName)
	for pattern, size := range knownModelSizes {
		if strings.Contains(name, pattern) {
			return uint64(float64(size) * vramMultiplier)
		}
	}
	return 0
}

// knownModelSizes maps common parameter-count hints to approximate GGUF file bytes.
var knownModelSizes = map[string]uint64{
	"0.5b": 500 * 1024 * 1024, // ~500 MiB
	"1b":   1 << 30,           // ~1 GiB
	"1.5b": 1.5 * 1024 * 1024 * 1024,
	"2b":   2 << 30,  // ~2 GiB
	"3b":   3 << 30,  // ~3 GiB
	"7b":   4 << 30,  // ~4 GiB (Q4_K_M)
	"8b":   5 << 30,  // ~5 GiB
	"13b":  8 << 30,  // ~8 GiB
	"14b":  9 << 30,  // ~9 GiB
	"27b":  16 << 30, // ~16 GiB
	"30b":  20 << 30, // ~20 GiB
	"32b":  20 << 30, // ~20 GiB
	"70b":  40 << 30, // ~40 GiB
	"72b":  42 << 30, // ~42 GiB
}

// ResolveModelPath converts a HuggingFace model reference (e.g., "llama3:8b")
// to a local GGUF file path under the HF cache directory.
// Returns empty string if no matching blob is found.
func ResolveModelPath(hfCacheDir, modelRef string) string {
	// Strip tag suffix for directory lookup: "llama3:8b" → "llama3"
	dirName := modelRef
	if i := strings.Index(modelRef, ":"); i >= 0 {
		dirName = modelRef[:i]
	}
	modelDir := filepath.Join(hfCacheDir, "models", dirName)

	var ggufPath string
	filepath.WalkDir(modelDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if !d.IsDir() && strings.HasSuffix(path, ".gguf") {
			ggufPath = path
			return fs.SkipAll
		}
		return nil
	})
	return ggufPath
}

