472	// TestLoadOrGet_InFlightProtection verifies that a model with an active
473	// in-flight request cannot be evicted; the caller gets a 503-style error.
474	func TestLoadOrGet_InFlightProtection(t *testing.T) {
475		cfg := &config.Config{
476			Models: map[string]config.ModelParams{
477				"org/model-a": {Slots: 1},
478				"org/model-b": {Slots: 1},
479			},
480			Warmup:    []string{"org/model-a"},
481			MaxModels: 1,
482		}
483		m := newTestManager(cfg)
484	
485		ctx, cancel := context.WithCancel(context.Background())
486		defer cancel()
487		if err := m.Start(ctx); err != nil {
488			t.Fatalf("Start: %v", err)
489		}
490	
491		waitLoadedModel(t, m, "org/model-a", 10*time.Second)
492	
493		// Hold an in-flight request against model A.
494		_, releaseA, err := m.LoadOrGet(ctx, "org/model-a", cfg.Models["org/model-a"])
495		if err != nil {
496			t.Fatalf("LoadOrGet model-a: %v", err)
497		}
498		// Do NOT call releaseA yet — this keeps inflight > 0.
499	
500		// Requesting model B at max_models=1 must fail because A has in-flight requests.
501		_, _, err = m.LoadOrGet(ctx, "org/model-b", cfg.Models["org/model-b"])
502		if err == nil {
503			t.Fatal("expected error when trying to evict a model with in-flight requests, got nil")
504		}
505	
506		// Now release A; the next request for B should succeed.
507		releaseA()
508	
509		_, releaseB, err := m.LoadOrGet(ctx, "org/model-b", cfg.Models["org/model-b"])
510		if err != nil {
511			t.Fatalf("LoadOrGet model-b after release: %v", err)
512		}
513		releaseB()
514	}
515	
516	// TestLoadOrGet_ContextCancellation verifies that cancelling the requesting
517	// context does not abort the model load. A second request for the same model
518	// (with a valid context) should join the in-progress load.
519	func TestLoadOrGet_ContextCancellation(t *testing.T) {
520		cfg := &config.Config{
521			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
522			MaxModels: 1,
523		}
524		m := New(cfg, slog.Default())
525		// 400 ms delay so we can cancel the first request mid-load.
526		m.cmdBuilder = testCmdBuilderWithDelay(400)
527	
528		bgCtx, cancel := context.WithCancel(context.Background())
529		defer cancel()
530		if err := m.Start(bgCtx); err != nil {
531			t.Fatalf("Start: %v", err)
532		}
533	
534		params := config.ModelParams{Slots: 1}
535	
536		// First request: cancel the context almost immediately.
537		cancelCtx, cancelFn := context.WithCancel(bgCtx)
538		cancelFn() // cancel before LoadOrGet returns
539	
540		_, _, err := m.LoadOrGet(cancelCtx, "org/model-a", params)
541		if err == nil {
542			t.Log("first request: LoadOrGet returned before context cancelled (load was fast)")
543		} else if !errors.Is(err, context.Canceled) {
544			t.Fatalf("first request: expected context.Canceled, got %v", err)
545		}
546	
547		// The supervisor should still be running (using the manager's detached context).
548		// A second request with a valid context should succeed.
549		addr, release, err := m.LoadOrGet(bgCtx, "org/model-a", params)
550		if err != nil {
551			t.Fatalf("second LoadOrGet: %v", err)
552		}
553		defer release()
554		if addr == "" {
555			t.Fatal("second LoadOrGet: got empty addr")
556		}
557	}
558	
559	// TestLoadOrGet_LoadFailure verifies that when a model fails to start, all
560	// concurrent waiters receive an error and the model is removed from procs.
561	func TestLoadOrGet_LoadFailure(t *testing.T) {
562		cfg := &config.Config{
563			Models:    map[string]config.ModelParams{"org/bad-model": {Slots: 1}},
564			MaxModels: 2,
565		}
566		m := New(cfg, slog.Default())
567		m.cmdBuilder = failCmdBuilder            // process exits immediately
568		m.healthTimeout = 500 * time.Millisecond // short timeout so test is fast
569	
570		bgCtx, cancel := context.WithCancel(context.Background())
571		defer cancel()
572		if err := m.Start(bgCtx); err != nil {
573			t.Fatalf("Start: %v", err)
574		}
575	
576		params := config.ModelParams{Slots: 1}
577		const n = 5
578		var wg sync.WaitGroup
579		errs := make([]error, n)
580		wg.Add(n)
581		for i := range n {
582			go func(i int) {
583				defer wg.Done()
584				_, _, errs[i] = m.LoadOrGet(bgCtx, "org/bad-model", params)
585			}(i)
586		}
587		wg.Wait()
588	
589		// All waiters must have received an error.
590		for i, err := range errs {
591			if err == nil {
592				t.Errorf("goroutine %d: expected load error, got nil", i)
593			}
594		}
595	
596		// Model must not appear in ListModels (state idle = excluded).
597		for _, mi := range m.ListModels() {
598			if mi.ID == "org/bad-model" {
599				t.Errorf("failed model still visible in ListModels with status %q", mi.Status)
600			}
601		}
602	}
603	
604	// TestLoadOrGet_CapacityLimit verifies that when max_models=2 and both loaded
605	// models have in-flight requests, a third request returns an error.
606	func TestLoadOrGet_CapacityLimit(t *testing.T) {
607		cfg := &config.Config{
608			Models: map[string]config.ModelParams{
609				"org/model-a": {Slots: 1},
610				"org/model-b": {Slots: 1},
611			},
612			MaxModels: 2,
613		}
614		m := newTestManager(cfg)
615	
616		bgCtx, cancel := context.WithCancel(context.Background())
617		defer cancel()
618		if err := m.Start(bgCtx); err != nil {
619			t.Fatalf("Start: %v", err)
620		}
621	
622		params := config.ModelParams{Slots: 1}
623	
624		// Load both models and hold in-flight requests.
625		_, releaseA, err := m.LoadOrGet(bgCtx, "org/model-a", params)
626		if err != nil {
627			t.Fatalf("LoadOrGet model-a: %v", err)
628		}
629		_, releaseB, err := m.LoadOrGet(bgCtx, "org/model-b", params)
630		if err != nil {
631			t.Fatalf("LoadOrGet model-b: %v", err)
632		}
633	
634		// Third model with both in-flight: must fail.
635		_, _, err = m.LoadOrGet(bgCtx, "org/model-c", config.ModelParams{Slots: 1})
636		if err == nil {
637			t.Fatal("expected capacity error for third model with all models busy, got nil")
638		}
639	
640		releaseA()
641		releaseB()
642	}
643	
644	// ---------------------------------------------------------------------------
645	// Reload tests
646	// ---------------------------------------------------------------------------
647	
648	// TestReload_ParamsChanged verifies that a model with changed params is drained
649	// and restarted by Reload.
650	func TestReload_ParamsChanged(t *testing.T) {
651		cfg := &config.Config{
652			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
653			Warmup:    []string{"org/model-a"},
654			MaxModels: 1,
655		}
656		m := newTestManager(cfg)
657	
658		ctx, cancel := context.WithCancel(context.Background())
659		defer cancel()
660	
661		if err := m.Start(ctx); err != nil {
662			t.Fatalf("Start: %v", err)
663		}
664		waitLoadedModel(t, m, "org/model-a", 10*time.Second)
665	
666		// New config: same model, different params.
667		newCfg := &config.Config{
668			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 2}},
669			Warmup:    []string{"org/model-a"},
670			MaxModels: 1,
671		}
672		m.Reload(newCfg)
673	
674		// Model should restart and become healthy again.
675		waitLoadedModel(t, m, "org/model-a", 10*time.Second)
676	}
677	
678	// TestReload_ParamsUnchanged verifies that a model with unchanged params is NOT
679	// restarted by Reload — same port (same process) before and after.
680	func TestReload_ParamsUnchanged(t *testing.T) {
681		cfg := &config.Config{
682			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
683			Warmup:    []string{"org/model-a"},
684			MaxModels: 1,
685		}
686		m := newTestManager(cfg)
687	
688		ctx, cancel := context.WithCancel(context.Background())
689		defer cancel()
690	
691		if err := m.Start(ctx); err != nil {
692			t.Fatalf("Start: %v", err)
693		}
694		waitLoadedModel(t, m, "org/model-a", 10*time.Second)
695	
696		addrBefore, ok := m.Addr("org/model-a")
697		if !ok {
698			t.Fatal("Addr: expected ok=true before Reload")
699		}
700	
701		// Same params — should be a no-op for this model.
702		newCfg := &config.Config{
703			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
704			Warmup:    []string{"org/model-a"},
705			MaxModels: 1,
706		}
707		m.Reload(newCfg)
708	
709		if !m.Loaded("org/model-a") {
710			t.Fatal("model should still be loaded after no-op Reload")
711		}
712		addrAfter, ok := m.Addr("org/model-a")
713		if !ok {
714			t.Fatal("Addr: expected ok=true after Reload")
715		}
716		if addrBefore != addrAfter {
717			t.Errorf("addr changed after no-op Reload: %q → %q (model was restarted unexpectedly)", addrBefore, addrAfter)
718		}
719	}
720	
721	// TestReload_RemovedModel verifies that a running model not present in the new
722	// config is drained and removed by Reload.
723	func TestReload_RemovedModel(t *testing.T) {
724		cfg := &config.Config{
725			Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
726			Warmup:    []string{"org/model-a"},
727			MaxModels: 1,
728		}
729		m := newTestManager(cfg)
730	
731		ctx, cancel := context.WithCancel(context.Background())
732		defer cancel()
733	
734		if err := m.Start(ctx); err != nil {
735			t.Fatalf("Start: %v", err)
736		}
737		waitLoadedModel(t, m, "org/model-a", 10*time.Second)
738	
739		// New config: model-a removed entirely.
740		newCfg := &config.Config{
741			Models:    map[string]config.ModelParams{"org/model-b": {Slots: 1}},
742			Warmup:    []string{},
743			MaxModels: 1,
744		}
745		m.Reload(newCfg)
746	
747		if m.Loaded("org/model-a") {
748			t.Error("model-a should have been drained after Reload removed it")
749		}
750	
751		m.mu.RLock()
752		_, stillInProcs := m.procs["org/model-a"]
753		m.mu.RUnlock()
754		if stillInProcs {
755			t.Error("model-a should have been deleted from procs")
756		}
757	}
758	
759	// TestReload_NewWarmupModel verifies that a new warmup model in the updated
760	// config is started by Reload.
761	func TestReload_NewWarmupModel(t *testing.T) {
762		cfg := &config.Config{
763			Models: map[string]config.ModelParams{
764				"org/model-a": {Slots: 1},
765				"org/model-b": {Slots: 1},
766			},
767			Warmup:    []string{"org/model-a"},
768			MaxModels: 2,
769		}
770		m := newTestManager(cfg)
771	
772		ctx, cancel := context.WithCancel(context.Background())
773		defer cancel()
774	
775		if err := m.Start(ctx); err != nil {
776			t.Fatalf("Start: %v", err)
777		}
778		waitLoadedModel(t, m, "org/model-a", 10*time.Second)
779	
780		// New config: add model-b to warmup.
781		newCfg := &config.Config{
782			Models: map[string]config.ModelParams{
783				"org/model-a": {Slots: 1},
784				"org/model-b": {Slots: 1},
785			},
786			Warmup:    []string{"org/model-a", "org/model-b"},
787			MaxModels: 2,
788		}
789		m.Reload(newCfg)
790	
791		// model-b should be started and eventually healthy.
792		waitLoadedModel(t, m, "org/model-b", 10*time.Second)
793	}
794	
795	// ---------------------------------------------------------------------------
796	// Helpers
797	// ---------------------------------------------------------------------------
798	
799	// waitLoadedModel polls until the named model is healthy or the deadline passes.
800	func waitLoadedModel(t *testing.T, m *Manager, name string, timeout time.Duration) {
801		t.Helper()
802		deadline := time.Now().Add(timeout)
803		for time.Now().Before(deadline) {
804			if m.Loaded(name) {
805				return
806			}
807			time.Sleep(100 * time.Millisecond)
808		}
809		t.Fatalf("model %q did not become healthy within %v", name, timeout)
810	}
