	deadline := time.Now().Add(m.effectiveDrainTimeout())
	for ps.inflight.Load() > 0 {
		remaining := time.Until(deadline)
		if remaining <= 0 {
			m.log.Warn("drain timeout exceeded, forcing shutdown", "model", ps.modelName)
			break
		}
		sleep := 10 * time.Millisecond
		if remaining < sleep {
			sleep = remaining
		}
		time.Sleep(sleep)
	}
	ps.cancel()
}

