			ticket.succeed(addr, rel)
			return
		case stateLoading:
			m.mu.Unlock()
			<-ready2
			addr, rel, err := m.checkLoaded(modelName)
			if err != nil {
				ticket.fail(err)
			} else {
				ticket.succeed(addr, rel)
			}
			return
		}
	}

