	ps := &procState{
		modelName: modelName,
		params:    params,
		state:     stateLoading,
		ready:     make(chan struct{}),
		cancel:    modelCancel,
		isWarmup:  false,
	}
	m.procs[modelName] = ps
	ready := ps.ready
	m.mu.Unlock()

	m.publishEvent(monitor.ServerEvent{
		Time:    time.Now(),
		Backend: modelName,
		Kind:    monitor.EventModelLoad,
		Message: "loading on demand",
	})

