	defer cancel()

	if err := m.Start(ctx); err != nil {
		t.Fatalf("Start: %v", err)
	}
	waitLoadedModel(t, m, "org/model-a", 10*time.Second)

	// New config: add model-b to warmup.
	newCfg := &config.Config{
		Models: map[string]config.ModelParams{
			"org/model-a": {Slots: 1},
			"org/model-b": {Slots: 1},
