		t.Fatalf("Start: %v", err)
	}
	waitLoadedModel(t, m, "org/model-a", 10*time.Second)

	// New config: model-a removed entirely.
	newCfg := &config.Config{
		Models:    map[string]config.ModelParams{"org/model-b": {Slots: 1}},
		Warmup:    []string{},
		MaxModels: 1,
	}
