	addrBefore, ok := m.Addr("org/model-a")
	if !ok {
		t.Fatal("Addr: expected ok=true before Reload")
	}

	// Same params — should be a no-op for this model.
	newCfg := &config.Config{
		Models:    map[string]config.ModelParams{"org/model-a": {Slots: 1}},
