		} else {
			addr = a
			rel = func() {}
		}
	}

	if err != nil {
		return makeFailTicket(err)
	}
	return makeSuccessTicket(addr, rel)
}

func (m *mockManager) ListModels() []monitor.ModelInfo {
	return m.models
}

