	g.handleRoute(w, r)

	if w.Code != http.StatusOK {
		t.Errorf("status = %d, want 200", w.Code)
	}
	if receivedAuth != "Bearer sk-test-key" {
		t.Errorf("Authorization = %q, want %q", receivedAuth, "Bearer sk-test-key")
	}

